from matplotlib.ticker import ScalarFormatter,MaxNLocator,FuncFormatter
from style import new_figure,format_axes,export_figure,sha256,TEAL,BLUE,INK,ROAD,FLOW_CMAP,REPO

D=REPO/'docs'
def read(path):return json.loads(Path(path).read_text(encoding='utf-8'))
def source(path,role):return {'public_path':str(Path(path).relative_to(REPO)).replace('\\','/'),'sha256':sha256(path),'role':role}
def write_plot(stem,data):stem.with_suffix('.plot.json').write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
