 x=np.array([int(r['iteration']) for r in rows]);y=np.array([float(r['objective']) for r in rows]);gap=np.array([float(r['relative_gap']) for r in rows]);assert list(x)==list(range(6))
 ref=D/'assets/plot-semantics-r9/chicago/s20-fw-map-distribution.plot_data.json';r=read(ref);assert r['independent']['status']=='ACCEPTED';assert abs(float(r['independent']['objective_saved'])-y[-1])<1e-10
 title='Frank–Wolfe: S20 objective and relative gap';fig=new_figure('chicago',title,figsize=(10,4.7));axes=fig.subplots(1,2);fig.subplots_adjust(left=.08,right=.98,bottom=.17,top=.76,wspace=.29)
 a,b=axes
 a.plot(x,y,color=BLUE,marker='o',markersize=4,linewidth=1.6);a.set(title='Beckmann objective',xlabel='Saved iteration',ylabel='Objective (PCE·min/h)');a.ticklabel_format(axis='y',style='plain',useOffset=False);a.yaxis.set_major_formatter(FuncFormatter(lambda v,p:f'{v:,.1f}'));a.set_ylim(y.min()-.22,y.max()+.25)
 b.semilogy(x,gap,color=TEAL,marker='o',markersize=4,linewidth=1.6,label='Saved full-graph gap');b.axhline(1e-5,color=INK,ls='--',lw=1,label='Frozen gate: $10^{-5}$');b.set(title='Full-graph stopping check',xlabel='Saved iteration',ylabel='Relative gap (dimensionless)');b.legend(loc='upper right',fontsize=8);b.set_ylim(1e-6,2e-2)
 for ax in axes:format_axes(ax);ax.set_xticks(x);ax.set_xlim(-.18,5.18)
 caption=('Accepted Chicago Jane Byrne / West Loop R2 S20 Frank–Wolfe run. All six actual saved states, iterations 0–5, are plotted without smoothing or invented samples. The Beckmann objective is PCE·min/h on the frozen one-hour 1,754.9482512397267 PCE/h demand. The full-graph relative gap ends at 3.446136191653708e-6, below the unchanged 1e-5 gate. The small rise between saved gaps at iterations 3 and 4 is retained. This S20 method history is distinct from the separate four-state full-city presentation record. Numerical results are engineering scenarios, not observed traffic.')
