 sources=[source(p,'Six FW saved objective/gap states'),source(ref,'Independent accepted same-instance FW endpoint')];out=export_figure(fig,stem,rec,caption,sources);write_plot(stem,{'schema':'accepted-fw-history-v1','city':'chicago','instance':'R2 S20','rows':rows,'gate':1e-5,'unit':{'objective':'PCE·min/h','relative_gap':'dimensionless'}})
 items.append({'table_id':'chi-fw-history','originals':['assets/algorithm-transfer-r8/chicago/C06_S_convergence.svg'],'city':'chicago','title':title,'staged_stem':str(stem),'caption':caption,'source_hashes':sources,'route':rec['render_route'],'dimensions':out['dimensions'],'status':'RENDERED_PENDING_VISUAL_QA'})
 p=D/'assets/algorithm-transfer-r8/chicago/C06_T_physical_flow_plot_data.json';geo=D/'assets/plot-semantics-r9/chicago/fw-physical-flow.plot_data.json';status=D/'assets/algorithm-transfer-r8/CURRENT_STATUS.json';v=read(p);g=read(geo);receiver=next(r for r in read(status)['methods'] if r.get('city')=='chicago' and r.get('method')=='T_CG');assert receiver['receiver_status']=='ACCEPTED'
 ids=v['ordered_physical_ids'];flow=np.array(v['flow']['CG saved endpoint'],float);gids=g['physical_link_ids'];assert len(ids)==len(set(ids))==len(gids)==len(set(gids))==27129;assert set(ids)==set(gids);lookup=dict(zip(gids,g['display_segments_local_km']));segments=[lookup[k] for k in ids];assert len(flow)==len(segments);assert np.min(flow)>=0
 points=np.array([xy for seg in segments for xy in seg]);mins,maxs=points.min(0),points.max(0);ratio=(maxs[1]-mins[1])/(maxs[0]-mins[0]);positive=flow>0;norm=PowerNorm(gamma=.5,vmin=0,vmax=float(flow.max()));counts,edges=np.histogram(flow,bins=22,range=(0,float(flow.max())));assert int(counts.sum())==len(flow)
 title='Column generation: physical flow and distribution';fig=new_figure('chicago',title,figsize=(10,5.4));a=fig.add_axes([.07,.235,.4,.60]);b=fig.add_axes([.575,.235,.4,.60]);a.set_box_aspect(ratio);b.set_box_aspect(ratio)
 a.add_collection(LineCollection(segments,colors=ROAD,linewidths=.38,zorder=1));lc=LineCollection([segments[i] for i in np.flatnonzero(positive)],array=flow[positive],cmap=FLOW_CMAP,norm=norm,linewidths=1.2,zorder=3);a.add_collection(lc);pad=(maxs-mins)*.025;a.set_xlim(mins[0]-pad[0],maxs[0]+pad[0]);a.set_ylim(mins[1]-pad[1],maxs[1]+pad[1]);a.set(title='Own physical-link movement flow',xlabel='Local easting (km)',ylabel='Local northing (km)');format_axes(a,map_axis=True);a.xaxis.set_major_locator(MaxNLocator(5));a.yaxis.set_major_locator(MaxNLocator(5));cax=a.inset_axes([0,-.255,1,.035]);cb=fig.colorbar(lc,cax=cax,orientation='horizontal');cb.set_label('Physical-link pulse flow (PCE)',fontsize=9);cb.set_ticks([0,10,25,50]);cb.ax.tick_params(labelsize=8,length=2)
 b.bar(edges[:-1],counts,width=np.diff(edges),align='edge',color=TEAL,edgecolor='white',linewidth=.45,zorder=3);b.set(title='All physical-link flow values',xlabel='Physical-link pulse flow (PCE)',ylabel='Physical links (count)');b.set_xlim(0,float(flow.max()));b.set_ylim(0,max(counts)*1.075);b.yaxis.set_major_formatter(FuncFormatter(lambda value,pos:f'{value:,.0f}'));format_axes(b);b.text(.97,.96,f'{len(flow):,} physical links\n{int(np.count_nonzero(flow==0)):,} exact zeros',transform=b.transAxes,ha='right',va='top',fontsize=8,color=INK)
 caption=('Accepted Chicago R2 T4 column-generation endpoint on the original 30-second/H169 finite graph. The map sums this method’s own saved movement-arc flow over commodities and time onto each original physical-link ID; the unit is PCE in the selected pulse, not an hourly rate. The complete 27,129-link vector includes 26,597 exact zeros and 532 positive values. All physical links remain gray context, and positive links use a square-root sequential scale with original-unit colorbar ticks. The 22-bin histogram counts every physical link, including zeros, on a linear count axis. Public saved geometry is joined by a unique exact ID set; no static FW flow is reused. Ledger connectors are excluded. © OpenStreetMap contributors; road-derived data ODbL 1.0: https://www.openstreetmap.org/copyright. Numerical results are engineering scenarios, not observed traffic.')
 stem=output/'chi-cg-physical';rec={'figure_id':'R12-CHI-CG-PHYSICAL','city':'chicago','instance':receiver['instance'],'role':'spatial','conclusion':'Accepted CG own pulse flow is localized over a sparse subset of the retained physical road network.','panels':[{'quantity':'Own physical-link CG movement flow','unit':'PCE'},{'quantity':'All-link CG flow distribution','unit':'link count / PCE bins'}],'quantity':['Physical-link pulse flow','Physical-link counts'],'unit':['PCE','count'],'render_route':'Saved-data replot; approved CG flow joined to approved original physical geometry by exact unique persistent IDs.','geometry_join':{'flow_count':len(ids),'geometry_count':len(gids),'unique_id_sets_equal':True,'geometry_projected_crs':g['projected_crs'],'local_origin_projected_metres':g['local_origin_projected_metres'],'no_other_method_flow_read':True},'statistics':{'exact_zero':int(np.count_nonzero(flow==0)),'positive':int(positive.sum()),'minimum':float(flow.min()),'maximum':float(flow.max()),'histogram_count':int(counts.sum())},'acceptance':receiver,'no_failed_attempts_displayed':True}
