 items.append({'table_id':'chi-cg-physical','originals':['assets/algorithm-transfer-r8/chicago/C06_T_physical_flow.svg'],'city':'chicago','title':title,'staged_stem':str(stem),'caption':caption,'source_hashes':sources,'route':rec['render_route'],'dimensions':out['dimensions'],'status':'RENDERED_PENDING_VISUAL_QA'})
 manifest={'schema':'r12-accepted-mixed-render-v1','renderer':str(Path(__file__).relative_to(REPO)).replace('\\','/'),'solver_calls':0,'matcher_calls':0,'items':items}
